tick=()=>{try{if(!EditorApplication.isPlaying){Finish("Play stopped");return;}if(!started){if(!Application.isFocused)return;started=true;start=EditorApplication.timeSinceStartup;}if(!Application.isFocused){Finish("Focus lost");return;}if(frame==Time.frameCount)return;frame=Time.frameCount;double elapsed=EditorApplication.timeSinceStartup-start;bool walking=elapsed>1.2&&elapsed<12.5;var world=elapsed<9.0?Vector3.right:Vector3.forward;var local=Quaternion.Inverse(Quaternion.Euler(0,camera.transform.eulerAngles.y,0))*world;UnityEngine.InputSystem.InputSystem.QueueStateEvent(pad,new UnityEngine.InputSystem.LowLevel.GamepadState{leftStick=walking?new Vector2(local.x,local.z)*.55f:Vector2.zero});string key=null;var state=animator.GetCurrentAnimatorStateInfo(0);float phase=Mathf.Repeat(state.normalizedTime,1);if(elapsed>.6&&elapsed<1.1)key="Idle";if(elapsed>2&&elapsed<8.5&&state.IsName("Walk")&&!animator.IsInTransition(0)){if(phase<.10f)key="Walk_A";else if(phase>.23f&&phase<.33f)key="Walk_B";else if(phase>.48f&&phase<.58f)key="Walk_C";else if(phase>.73f&&phase<.83f)key="Walk_D";}if(elapsed>9.5&&elapsed<11.5)key="Turning";if(elapsed>13.5)key="Stopped";if(key!=null&&captures.Add(key))Record(key);if(elapsed>14.5)Finish();}catch(System.Exception ex){Finish(ex.ToString());}};EditorApplication.update+=tick;return "Rig visual cycle armed; waiting for Game focus";
